sys_ux_data_broker_transform.script:
function transform(input) {
    var usersFields = [];
    var contractFields = [];

    // Create a GlideRecord for 'u_snow_customisation' table
    var customisationGR = new GlideRecord('u_snow_customisation');

    // Order by sys_created_on field in descending order (most recent first)
    customisationGR.orderByDesc('sys_created_on');

    // Query the table to get the most recent record
    customisationGR.query();

    // Retrieve the first (most recent) record
    if (customisationGR.next()) {
        // Iterate through each field in the record
        for (var field in customisationGR) {
            if (customisationGR.isValidField(field)) {
                var fieldValue = customisationGR.getElement(field);
                gs.log("Field Name: " + field + ", Field Value: " + fieldValue);

                // Check if the field value ends with 'users' and add it to usersFields
                if (field && field.endsWith('users')) {
                    usersFields.push({
                        fieldName: field,  // Add the field name to the array
                        fieldValue: fieldValue
                    });
                }

                // Check if the field value ends with 'contract' and add it to contractFields
                else if (field && field.endsWith('contract')) {
                    contractFields.push({
                        fieldName: field,  // Add the field name to the array
                        fieldValue: fieldValue
                    });
                }
            }
        }
    }

    // Ensure the outputs object is populated with the needed values
    var outputs = {
        usersFields: usersFields,
        contractFields: contractFields
    };

    // Log the outputs for debugging
    gs.log("Users Fields: " + JSON.stringify(usersFields));
    gs.log("Contract Fields: " + JSON.stringify(contractFields));

    // Return the outputs so that UI Builder can access them
    return {
        snowreport_1: outputs
    };
}
